import React, { useState } from 'react';
import { CPopupEdit, Message } from '@cloud-materials/common';

export default () => {
  const [value, setValue] = useState('异步关闭弹窗，确定按钮loading');

  return (
    <div style={{ display: 'flex', justifyContent: 'center' }}>
      <CPopupEdit
        defaultValue={value}
        title="修改名称"
        onOk={(newValue: string) => {
          return new Promise<any>((rs, rj) => {
            setTimeout(() => {
              if (Math.random() > 0.5) {
                setValue(newValue);
                rs('');
              } else {
                rj('');
                Message.error('发生错误请重试');
              }
            }, 1000);
          });
        }}
      />
    </div>
  );
};

